165	func TestOfflineEnvironCutsTheNetworkAndKeepsTheRest(t *testing.T) {
166		tests := []struct {
167			name string
168			base []string
169			// kept are entries that must come out untouched, in this order.
170			kept []string
171		}{
172			{"no base", nil, nil},
173			{"nothing of the network in it", []string{"PATH=/usr/bin", "HOME=/home/u"},
174				[]string{"PATH=/usr/bin", "HOME=/home/u"}},
175			{"the host's proxy, both casings",
176				[]string{"PATH=/usr/bin",
177					"HTTP_PROXY=REDACTED", "http_proxy=REDACTED",
178					"HTTPS_PROXY=REDACTED", "https_proxy=REDACTED",
179					"ALL_PROXY=socks5://proxy.example:1080", "all_proxy=socks5://proxy.example:1080",
180					"NO_PROXY=.corp.example", "no_proxy=.corp.example", "LANG=fr_FR.UTF-8"},
181				[]string{"PATH=/usr/bin", "LANG=fr_FR.UTF-8"}},
182			{"a git protocol list, a locale and a request method",
183				[]string{"GIT_ALLOW_PROTOCOL=https:ssh", "LC_ALL=fr_FR.UTF-8", "REQUEST_METHOD=GET", "TERM=xterm"},
184				[]string{"TERM=xterm"}},
185			{"the user's ssh identity and git commands",
186				[]string{"HOME=/home/u", "SSH_AUTH_SOCK=/tmp/agent.1", "GIT_SSH=/usr/bin/ssh", "GIT_SSH_COMMAND=ssh -i /home/u/.ssh/id",
187					"GIT_PROXY_COMMAND=/usr/bin/nc", "GIT_TERMINAL_PROMPT=1", "XDG_RUNTIME_DIR=/run/user/1000"},
188				[]string{"HOME=/home/u", "XDG_RUNTIME_DIR=/run/user/1000"}},
189			{"values holding an equal sign", []string{"A=b=c", "SOME_SOCK=/tmp/x=y"},
190				[]string{"A=b=c", "SOME_SOCK=/tmp/x=y"}},
191			{"a variable that only looks like one of them", []string{"MY_HTTP_PROXY=x", "GIT_ALLOW_PROTOCOL_X=y", "LC_ALL_X=z", "PROXY=1"},
192				[]string{"MY_HTTP_PROXY=x", "GIT_ALLOW_PROTOCOL_X=y", "LC_ALL_X=z", "PROXY=1"}},
193		}
194		for _, tt := range tests {
195			t.Run(tt.name, func(t *testing.T) {
196				snapshot := slices.Clone(tt.base)
197	
198				got := offlineEnviron(tt.base)
199	
200				checkOffline(t, got)
201				var kept []string
202				for _, kv := range got {
203					if slices.Contains(tt.kept, kv) {
204						kept = append(kept, kv)
205					}
206				}
207				if !slices.Equal(kept, tt.kept) {
208					t.Errorf("the other variables = %q, want %q, in this order", kept, tt.kept)
209				}
210				if !slices.Equal(tt.base, snapshot) {
211					t.Errorf("the base was modified: %q, was %q", tt.base, snapshot)
212				}
213				for i := range got {
214					got[i] = "X=changed"
215				}
216				if !slices.Equal(tt.base, snapshot) {
217					t.Errorf("the result shares memory with the base: %q, was %q", tt.base, snapshot)
218				}
219			})
220		}
221	}
