223	// A secret the host holds in its proxy variable is not in what the renderer is
224	// handed, by any name.
225	func TestOfflineEnvironDoesNotCarryTheHostProxyAnywhere(t *testing.T) {
226		got := offlineEnviron([]string{"HTTPS_PROXY=REDACTED", "https_proxy=REDACTED"})
227	
228		for _, kv := range got {
229			if strings.Contains(kv, "s3cr3tpw") || strings.Contains(kv, "proxy.example") {
