237	func TestAnOfflineContainerRunCutsTheNetworkAndForwardsNoProxy(t *testing.T) {
238		noProxyEnvironment(t)
239		useProxy(t, forwardOf(fullProxy))
240		forEachEngine(t, func(t *testing.T, binary string) {
241			got := containerRun{
242				Flags:   []string{"-v", "/repo:/scan:ro", "-w", "/scan"},
243				Image:   "img:1",
244				Argv:    []string{"build", "./overlay"},
245				Stdin:   []byte("in"),
246				Offline: true,
247			}.cmd()
248	
249			want := []string{"run", "--rm", "-v", "/repo:/scan:ro", "-w", "/scan", "--network", "none", "img:1", "build", "./overlay"}
250			if got.Name != binary || !slices.Equal(got.Args, want) {
251				t.Errorf("cmd = %s %q, want %s %q", got.Name, got.Args, binary, want)
252			}
253			for _, name := range netproxy.ForwardedVariables {
254				if slices.Contains(got.Args, name) {
255					t.Errorf("argv names %s although the container is offline: %q", name, got.Args)
256				}
257			}
258			if got.Env != nil {
259				t.Errorf("Env = %q, want nil: nothing to forward and nothing extra", got.Env)
260			}
261			if string(got.Stdin) != "in" {
262				t.Errorf("Stdin = %q, want it carried", got.Stdin)
263			}
264		})
265	}
