268	// and the proxy values still do not.
269	func TestAnOfflineContainerRunKeepsItsOwnEnvironmentButNoProxy(t *testing.T) {
270		noProxyEnvironment(t)
271		useProxy(t, forwardOf(fullProxy))
272		forEachEngine(t, func(t *testing.T, _ string) {
273			got := containerRun{
274				Flags:   []string{"-e", "TOKEN"},
275				Image:   "img:1",
276				Env:     []string{"TOKEN=t0k3n"},
277				Offline: true,
278			}.cmd()
279	
280			if want := []string{"run", "--rm", "-e", "TOKEN", "--network", "none", "img:1"}; !slices.Equal(got.Args, want) {
281				t.Errorf("Args = %q, want %q", got.Args, want)
282			}
283			if !slices.Contains(got.Env, "TOKEN=t0k3n") {
284				t.Errorf("Env lost the caller's variable: %q", got.Env)
285			}
286			checkProxyEnv(t, got.Env, nil)
287			for _, kv := range got.Env {
288				checkNoLeak(t, "Env entry", kv)
289			}
290		})
291	}
