293	// Online is what it was: the proxy is forwarded and nothing cuts the network.
294	func TestAContainerRunThatIsNotOfflineIsUnchanged(t *testing.T) {
295		fwd := forwardOf(fullProxy)
296		useProxy(t, fwd)
297		forEachEngine(t, func(t *testing.T, _ string) {
298			got := containerRun{Flags: []string{"-w", "/scan"}, Image: "img:1", Argv: []string{"x"}}.cmd()
299	
300			if slices.Contains(got.Args, "--network") || slices.Contains(got.Args, "none") {
301				t.Errorf("a run that is not offline cut the network: %q", got.Args)
302			}
303			want := slices.Concat([]string{"run", "--rm", "-w", "/scan"}, pairsOf(netproxy.ForwardedVariables), []string{"img:1", "x"})
304			if !slices.Equal(got.Args, want) {
305				t.Errorf("Args = %q, want %q", got.Args, want)
306			}
307			checkProxyEnv(t, got.Env, bothCasings(fullProxy))
308		})
309	}
