311	// ── What the scan hands to helm, kustomize and kubeconform ───────────────────
312	
313	// networkRunner answers every tool of the schema stage with a success, or with
314	// kustomizeErr for `kustomize build`, and records what it was asked. git (asked
315	// for the mount of a container renderer) has no repository to name.
316	func networkRunner(t *testing.T, kustomizeErr string) *scriptedRunner {
317		t.Helper()
318		lint := "==> Linting charts/api\n\n1 chart(s) linted, 0 chart(s) failed\n"
319		r := &scriptedRunner{}
320		r.reply = func(tc toolCmd) ([]byte, error) {
321			if tc.Name == "git" {
322				return nil, &exitError{Code: 128, Stderr: "not a git repository"}
323			}
324			switch subcommandOf(tc) {
325			case "lint":
326				return []byte(lint), nil
327			case "template":
328				return []byte("apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: cm\n"), nil
329			case "build":
330				if kustomizeErr != "" {
331					return nil, &exitError{Code: 1, Stderr: kustomizeErr}
332				}
333				return []byte("apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: worker\n"), nil
334			}
335			return []byte(`{"resources":[]}`), nil
336		}
337		useRunner(t, r)
338		return r
339	}
340	
341	// callsTo is the recorded invocations that satisfy pred.
342	func (r *scriptedRunner) callsTo(pred func(toolCmd) bool) []toolCmd {
343		r.mu.Lock()
344		defer r.mu.Unlock()
345		var out []toolCmd
346		for _, c := range r.calls {
347			if pred(c) {
348				out = append(out, c)
349			}
350		}
351		return out
352	}
353	
354	// renderCall is the one invocation of a helm or kustomize subcommand.
355	func renderCall(t *testing.T, r *scriptedRunner, sub string) toolCmd {
356		t.Helper()
357		calls := r.callsTo(func(tc toolCmd) bool { return subcommandOf(tc) == sub })
358		if len(calls) != 1 {
359			t.Fatalf("%d calls of %q, want 1, among %q", len(calls), sub, r.commands())
360		}
361		return calls[0]
362	}
363	
364	// kubeconformCall is the invocation that validates what was rendered.
365	func kubeconformCall(t *testing.T, r *scriptedRunner) toolCmd {
366		t.Helper()
367		calls := r.callsTo(func(tc toolCmd) bool { return len(tc.Stdin) > 0 })
368		if len(calls) == 0 {
369			t.Fatalf("nothing was handed to kubeconform, among %q", r.commands())
370		}
371		return calls[0]
372	}
373	
374	// networkNoneBefore reports whether the argv holds `--network none`, once,
375	// before the image: after the image it would be the tool's own argument.
376	func networkNoneBefore(args []string, image string) bool {
377		at := slices.Index(args, "--network")
378		img := slices.Index(args, image)
379		return slices.Index(args[at+1:], "--network") < 0 && at >= 0 && img > at+1 && args[at+1] == "none"
380	}
