387	// The option reaches the schema stage.
388	func TestTheSchemaStageIsToldWhetherRemoteBasesAreAllowed(t *testing.T) {
389		isolateHome(t)
390		deps := renderingDeps()
391	
392		if newScannerWithDeps(k8sSchemaFor("1.36.0"), deps).kubeconformOptions().AllowRemoteBases {
393			t.Error("remote bases are allowed by default")
394		}
395		if !newScannerWithDeps(allowRemoteBases(k8sSchemaFor("1.36.0")), deps).kubeconformOptions().AllowRemoteBases {
396			t.Error("scan.tools.kustomize.allow_remote_bases did not reach the schema stage")
397		}
398	}
