400	// A renderer that runs on this machine is handed an environment that cuts the
401	// network: the host's proxy and ssh transport are never reached, whatever this
402	// process holds.
403	func TestNativeRenderersRunWithTheNetworkCut(t *testing.T) {
404		isolateHome(t)
405		t.Setenv("HTTPS_PROXY", "REDACTED")
406		t.Setenv("GIT_ALLOW_PROTOCOL", "https:ssh")
407		t.Setenv("LC_ALL", "fr_FR.UTF-8")
408		r := networkRunner(t, "")
409	
410		result, _ := newScannerWithDeps(k8sSchemaFor("1.36.0"), renderingDeps()).
411			Scan(t.Context(), renderRepo(t), TargetDirectory)
412	
413		if len(result.Errors) != 0 {
414			t.Fatalf("errors = %v", result.Errors)
415		}
416		for _, sub := range []string{"build", "lint", "template"} {
417			t.Run(sub, func(t *testing.T) {
418				call := renderCall(t, r, sub)
419				if call.Env == nil {
420					t.Fatal("Env is nil: the renderer inherits this process's environment")
421				}
422				checkOffline(t, call.Env)
423				for _, kv := range call.Env {
424					checkNoLeak(t, "Env entry", kv)
425					if strings.Contains(kv, "s3cr3tpw") {
426						t.Errorf("Env carries the host's proxy: %q", kv)
427					}
428				}
429				if call.Dir == "" {
430					t.Error("the renderer no longer runs in the scanned directory")
431				}
432			})
433		}
434	}
435	
436	// Only the render is cut: kubeconform downloads the schemas it validates
437	// against, and is given the network it had.
438	func TestKubeconformKeepsTheNetworkWhenTheRenderersLoseIt(t *testing.T) {
439		isolateHome(t)
440		r := networkRunner(t, "")
441	
442		_, _ = newScannerWithDeps(k8sSchemaFor("1.36.0"), renderingDeps()).Scan(t.Context(), renderRepo(t), TargetDirectory)
443	
444		call := kubeconformCall(t, r)
445		if slices.Contains(valuesOf(call.Env, "GIT_ALLOW_PROTOCOL"), "devdesk-none") || slices.Contains(valuesOf(call.Env, "HTTPS_PROXY"), "http://127.0.0.1:0") {
446			t.Errorf("kubeconform runs with the network cut: %q", call.Env)
447		}
448	}
