311	// ── What the scan hands to helm, kustomize and kubeconform ───────────────────
312	
313	// networkRunner answers every tool of the schema stage with a success, or with
314	// kustomizeErr for `kustomize build`, and records what it was asked. git (asked
315	// for the mount of a container renderer) has no repository to name.
316	func networkRunner(t *testing.T, kustomizeErr string) *scriptedRunner {
317		t.Helper()
318		lint := "==> Linting charts/api\n\n1 chart(s) linted, 0 chart(s) failed\n"
319		r := &scriptedRunner{}
320		r.reply = func(tc toolCmd) ([]byte, error) {
321			if tc.Name == "git" {
322				return nil, &exitError{Code: 128, Stderr: "not a git repository"}
323			}
324			switch subcommandOf(tc) {
325			case "lint":
326				return []byte(lint), nil
327			case "template":
328				return []byte("apiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: cm\n"), nil
329			case "build":
330				if kustomizeErr != "" {
331					return nil, &exitError{Code: 1, Stderr: kustomizeErr}
332				}
333				return []byte("apiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: worker\n"), nil
334			}
335			return []byte(`{"resources":[]}`), nil
336		}
337		useRunner(t, r)
338		return r
339	}
