12	// handleTerminalBlur records that the terminal lost the focus. Nothing else
13	// happens here: the live animation chain's in-flight tick reaches
14	// handleAnimationTick, wantedCadence says no, and the chain is not renewed
15	// (DEVDESK-210). No generation bump is needed. On the edge only, the view on
16	// screen is told.
17	func (a *App) handleTerminalBlur() (tea.Model, tea.Cmd) {
18		if a.terminalBlurred {
19			return a, nil
20		}
21		a.terminalBlurred = true
22		if a.runWhenUnfocused {
23			return a, nil
24		}
25		return a, a.sendFocusTo(a.currentView, false)
26	}
27	
28	// handleTerminalFocus clears the blur. A focus with no prior blur changes
29	// nothing (an unknown focus means focused) and tells nobody. After a blur, the
30	// view on screen is asked to resume. The Update wrapper's ensureTick restarts
31	// the one chain when something needs it.
32	func (a *App) handleTerminalFocus() (tea.Model, tea.Cmd) {
33		if !a.terminalBlurred {
34			return a, nil
35		}
36		a.terminalBlurred = false
37		if a.runWhenUnfocused {
38			return a, nil
39		}
40		return a, a.sendFocusTo(a.currentView, true)
41	}
42	
43	// sendFocusTo hands one view the terminal focus state. It never calls Init,
44	// starts no scan and sets no footer message; the view decides what to do with
45	// it. resume is true only when the focus comes back after a blur.
46	func (a *App) sendFocusTo(target command.ViewType, resume bool) tea.Cmd {
47		view, ok := a.views[target]
48		if !ok {
49			return nil
50		}
51		updated, cmd := view.Update(shared.TerminalFocusMsg{Focused: !a.suspended(), Resume: resume && !a.suspended()})
52		a.setView(target, updated)
53		return cmd
54	}
55	
56	// suspended reports whether the terminal is blurred and the policy pauses.
57	func (a *App) suspended() bool { return a.terminalBlurred && !a.runWhenUnfocused }
58	
59	// wantedCadence is cadence() for the router's current state: while the terminal
60	// is blurred no chain is wanted, whatever the views or the jobs ask for.
61	func (a *App) wantedCadence() (time.Duration, bool) {
62		if a.suspended() {
63			return 0, false
64		}
65		return cadence(a.jobs.Running() > 0, a.wantsBlink(), a.motionStatic)
66	}
