100	// tick's own time, hands it to the view on screen, and renews the chain for as
101	// long as something needs it, at the cadence the need has now.
102	//
103	// The chain stops by not being renewed. It never stops on an "off" phase: a row
104	// is left on a steady "on" glyph.
105	func (a *App) handleAnimationTick(msg animationTickMsg) (tea.Model, tea.Cmd) {
106		if msg.seq != a.anim.seq {
107			return a, nil
108		}
109		d, ok := a.wantedCadence()
110		if !ok {
111			a.anim.ticking = false
112			// A blur always hands the view one last pinned frame: the tick that
113			// lands after it is the last the view will see for a while.
114			if a.anim.blinkOn && !a.suspended() {
115				return a, nil
116			}
117			a.anim.blinkOn = true
118			return a, a.sendFrameTo(a.currentView)
119		}
120		a.anim.blinkOn = a.motionStatic || blinkPhase(msg.at)
121		a.anim.interval = d
122		return a, tea.Batch(a.sendFrameTo(a.currentView), animationTick(a.anim.seq, d))
123	}
